file_put_contents($dir.'banana-radiation-calculator.blade.php',t('fas fa-radiation','Banana Radiation Calculator','Convert radiation exposure to Banana Equivalent Doses','<div class="row g-3"><div class="col-md-6"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Radiation (μSv)</label><input type="number" id="in-usv" class="form-control form-control-lg" value="10" step="0.1"></div><div class="col-md-6"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Or Enter BED</label><input type="number" id="in-bed" class="form-control form-control-lg" value="" placeholder="optional" step="1"></div></div>','<b>1 BED = 0.1 μSv</b> (potassium-40 in one banana)','document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var usv=document.getElementById("in-usv").value,bed=document.getElementById("in-bed").value;var usvVal,bedVal;if(bed){bedVal=parseFloat(bed);usvVal=bedVal*0.1;}else{usvVal=parseFloat(usv)||0;bedVal=usvVal/0.1;}document.getElementById("out-main").textContent=bedVal.toFixed(1);document.getElementById("out-unit").textContent="Banana Equivalent Doses (BED)";document.getElementById("out-detail").innerHTML=\'<div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">μSv</div><div class="h5 fw-bold mb-0 text-primary">\'+usvVal.toFixed(2)+\'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">mSv</div><div class="h5 fw-bold mb-0 text-info">\'+(usvVal/1000).toFixed(4)+\'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Bananas 🍌</div><div class="h5 fw-bold mb-0 text-warning">\'+Math.round(bedVal)+\'</div></div></div>\';var ins=[];ins.push(usvVal.toFixed(2)+" μSv = <b>"+bedVal.toFixed(1)+" bananas</b>");if(bedVal<1)ins.push("Less radiation than eating a single banana!");else if(bedVal>1000)ins.push("⚠ Significant exposure — equivalent to "+Math.round(bedVal)+" bananas.");document.getElementById("out-ins").innerHTML=\'<ul class="list-unstyled mb-0">\'+ins.map(function(x){return\'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>\'+x+"</li>";}).join("")+"</ul>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-usv").value=10;document.getElementById("in-bed").value="";document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText(document.getElementById("out-main").textContent+" BED");var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\\"fas fa-copy me-1\\"></i>Copy";},2e3);});});'));
