file_put_contents($dir.'falling-through-earth.blade.php',t('fas fa-globe','Falling Through Earth','Calculate gravity tunnel transit time (SHM)','<div class="row g-3"><div class="col-md-6"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Earth Radius (km)</label><input type="number" id="in-r" class="form-control form-control-lg" value="6371" step="1"></div><div class="col-md-6"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Surface Gravity (m/s²)</label><input type="number" id="in-g" class="form-control form-control-lg" value="9.81" step="0.01"></div><div class="col-md-6"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Object Mass (kg)</label><input type="number" id="in-m" class="form-control form-control-lg" value="70" step="0.1"></div></div>','<b>Formula:</b> T = 2π√(R/g) ≈ 42.2 minutes (Simple Harmonic Motion)','document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var R=parseFloat(document.getElementById("in-r").value)*1000||6371000,g=parseFloat(document.getElementById("in-g").value)||9.81;var T=2*Math.PI*Math.sqrt(R/g);var half=T/2;var vmax=Math.sqrt(g*R);document.getElementById("out-main").textContent=(T/60).toFixed(2);document.getElementById("out-unit").textContent="minutes (full round trip)";document.getElementById("out-detail").innerHTML=\'<div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">One Way</div><div class="h5 fw-bold mb-0 text-primary">\'+(half/60).toFixed(2)+\' min</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Max Speed</div><div class="h5 fw-bold mb-0 text-danger">\'+(vmax/1000).toFixed(1)+\' km/s</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Period</div><div class="h5 fw-bold mb-0 text-info">\'+T.toFixed(1)+\' s</div></div></div>\';document.getElementById("out-ins").innerHTML="<p>T = 2π√("+R/1000+"km / "+g+") = <b>"+(T/60).toFixed(2)+" min</b>. Max velocity at center: <b>"+(vmax/1000).toFixed(1)+" km/s</b></p>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-r").value=6371;document.getElementById("in-g").value=9.81;document.getElementById("in-m").value=70;document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText("Transit: "+document.getElementById("out-main").textContent+" min");var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\\"fas fa-copy me-1\\"></i>Copy";},2e3);});});'));
