file_put_contents($dir.'penny-drop-impact.blade.php',t('fas fa-coins','Penny Drop Impact','Calculate terminal velocity and impact force of a falling penny','<div class="row g-3"><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Drop Height (m)</label><input type="number" id="in-h" class="form-control form-control-lg" value="381" step="1"><div class="form-text">Empire State=381m</div></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Penny Mass (g)</label><input type="number" id="in-m" class="form-control form-control-lg" value="2.5" step="0.1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Initial Velocity (m/s)</label><input type="number" id="in-v0" class="form-control form-control-lg" value="0" step="0.1"></div><div class="col-12"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="in-air" checked><label class="form-check-label small fw-bold text-secondary" for="in-air">Include Air Resistance</label></div></div></div>','<b>Formula:</b> v = √(2gh) without air; Terminal v ≈ 11 m/s with drag','document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var h=parseFloat(document.getElementById("in-h").value)||0,m=(parseFloat(document.getElementById("in-m").value)||2.5)/1000,v0=parseFloat(document.getElementById("in-v0").value)||0,air=document.getElementById("in-air").checked;var g=9.81;var vNoAir=Math.sqrt(v0*v0+2*g*h);var vt=11;var v=air?Math.min(vNoAir,vt):vNoAir;var ke=0.5*m*v*v;var t=air?(vt/g)*Math.acosh(Math.exp(g*h/(vt*vt))):Math.sqrt(2*h/g);document.getElementById("out-main").textContent=v.toFixed(2);document.getElementById("out-unit").textContent="m/s impact velocity";document.getElementById("out-detail").innerHTML=\'<div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Velocity</div><div class="h5 fw-bold mb-0 text-primary">\'+v.toFixed(2)+\' m/s</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">KE</div><div class="h5 fw-bold mb-0 text-danger">\'+ke.toFixed(4)+\' J</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Fall Time</div><div class="h5 fw-bold mb-0 text-info">\'+t.toFixed(2)+\' s</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">km/h</div><div class="h5 fw-bold mb-0 text-warning">\'+(v*3.6).toFixed(1)+\'</div></div></div>\';var ins=["Impact at <b>"+v.toFixed(2)+" m/s ("+(v*3.6).toFixed(1)+" km/h)</b>"];if(air)ins.push("Terminal velocity limits speed to ~11 m/s due to drag.");ins.push("Kinetic energy: <b>"+ke.toFixed(4)+" J</b> — "+(ke<0.05?"harmless":"noticeable but not deadly"));document.getElementById("out-ins").innerHTML=\'<ul class="list-unstyled mb-0">\'+ins.map(function(x){return\'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>\'+x+"</li>";}).join("")+"</ul>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-h").value=381;document.getElementById("in-m").value=2.5;document.getElementById("in-v0").value=0;document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText("Impact: "+document.getElementById("out-main").textContent+" m/s");var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\\"fas fa-copy me-1\\"></i>Copy";},2e3);});});'));
